use siderust::{bodies::solar_system::{Moon,Mars},coordinates::{cartesian::Direction,frames::ICRS,surface::SurfaceSite,transform::{AstroContext,SurfaceHorizontalExt,horizontal_observation_to_direction}}};use qtty::{DEG,M};fn main(){let a=SurfaceSite::<Moon>::new(0.*DEG,0.*DEG,0.*M).unwrap();let b=SurfaceSite::<Mars>::new(0.*DEG,0.*DEG,0.*M).unwrap();let c:AstroContext=AstroContext::new();let t=siderust::J2000;let d=Direction::<ICRS>::new_unchecked(1.,0.,0.);let o=a.observe_direction(&d,&t,&c).unwrap();let _:Result<Direction<ICRS>,_>=horizontal_observation_to_direction(&o,&b,&t,&c);}
